React Single Page Application (SPA).diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component Diagram for the React Single Page Application (SPA) container

Container_Boundary("react_spa", "React Single Page Application (SPA)") {
    Component(Router & View Controller, "Router & View Controller", "React Router", "Manages client-side routing and page views for front desk, clinicians, billing, patients, and administrators.")
    Component(State Management & Data Fetching, "State Management & Data Fetching", "React Query", "Handles asynchronous data synchronization, caching, and state management for sub-second EMR loads.")
    Component(Authentication & Security Module, "Authentication & Security Module", "OAuth2 / OpenID Connect Client", "Manages user login tokens, session security, and MFA enforcement via HTTPS.")
}

System_Ext(API Gateway, "API Gateway", "NGINX/Kong API Gateway")

Rel(Router & View Controller, State Management & Data Fetching, "Triggers data fetching requests", "")
Rel(State Management & Data Fetching, API Gateway, "Sends perimeter requests via HTTPS", "HTTPS")

@enduml

API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway, "API Gateway") {
    Component(Kong_Gateway_Core, "Kong Gateway Core", "Kong, Lua", "Handles perimeter traffic routing, TLS 1.3 termination, and enforcement of security policies.")
    Component(OAuth2_MFA_Authentication_Module, "OAuth2 & MFA Authentication Module", "Lua Plugins", "Manages user authentication, OAuth2 token validation, and multi-factor authentication checks.")
    Component(Rate_Limiting_Traffic_Prioritization_Plugin, "Rate Limiting & Traffic Prioritization Plugin", "Lua Plugins", "Enforces distributed rate limits and prioritizes traffic across incoming requests.")
}

Rel(Kong_Gateway_Core, OAuth2_MFA_Authentication_Module, "Authenticates requests using", "")
Rel(Kong_Gateway_Core, Rate_Limiting_Traffic_Prioritization_Plugin, "Applies policies via", "")
@enduml

Apache Kafka Event Bus.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(apache_kafka_event_bus, "Apache Kafka Event Bus") {
    Component(Kafka_Brokers, "Kafka Brokers", "Apache Kafka, KRaft", "Handles distributed event streaming, log compaction, and message persistence across the event bus cluster.")
    Component(Schema_Registry, "Schema Registry", "Apache Avro", "Manages and validates data schemas for messages produced and consumed across core clinical and scheduling services.")
    Component(Strimzi_Operator, "Strimzi Operator", "Strimzi Operator", "Automates the management, provisioning, and scaling of the Apache Kafka cluster within the Kubernetes infrastructure.")
}

Rel(Kafka_Brokers, Schema_Registry, "Validates message schemas")
Rel(Strimzi_Operator, Kafka_Brokers, "Manages and deploys")
@enduml

Redis Cluster.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Redis Cluster container

Container_Boundary(redis_cluster, "Redis Cluster") {
    Component(RedisSentinelManager, "Redis Sentinel Manager", "Redis Sentinel", "Monitors the Redis instances and handles automatic failover for high availability.")
    Component(DistributedLockingEngine, "Distributed Locking Engine", "Redis Cluster with TLS (ioredis)", "Manages real-time distributed slot locking for the scheduling service.")
}

Rel(DistributedLockingEngine, RedisSentinelManager, "Monitored and managed for failover by", "")

@enduml
